mapper.select:

select #{start} time,a.app_name name,t.link_sum num
from (select app_type,sum(link_num) link_sum
       from TRAFFIC_APP_STATISTIC
       where stat_time>= #{start}
          and stat_time<#{end}
          group by app_type) t , ui_code_app_dic a
 where t.app_type=a.view_code;


select #{start} time,service type,sum(sum) num
from NTC_SERVICE_REPORT
where report_time>= #{start}
and report_time< #{end}
group by service;


SELECT pid id,num,LOG_URI url
  FROM MM_AUDIO_REPORT
  where report_time >= #{start}
  and report_time < #{end}
order by  num desc
limit 10


SELECT pid id,num,LOG_URI url
  FROM MM_VIDEO_REPORT
  where report_time >= #{start}
  and report_time < #{end}
   order by  num desc
limit 10


SELECT pid id,num,LOG_URI url
  FROM MM_PIC_REPORT
  where report_time >= #{start}
  and report_time < #{end}
   order by  num desc
limit 10


SELECT account phonenum,num,LOG_URI url
  FROM MM_VOIP_REPORT
  where report_time >= #{start}
  and report_time < #{end}
   order by  num desc
limit 10


	SELECT sum(MONITOR_NUM) as visitsNum,sum(REJECT_NUM)  as controlNum,sum(REPLACE_NUM) as replaceNum
        FROM pxy_total_report
        WHERE REPORT_TIME >= #{start}
       AND REPORT_TIME < #{end}

SELECT report_time
FROM NTC_TOTAL_REPORT

where report_time < #{end}

ORDER BY report_time desc
LIMIT 1;

SELECT stat_time
FROM TRAFFIC_APP_STATISTIC

where stat_time < #{end}

ORDER BY stat_time desc
LIMIT 1;

